diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
index 00fbfd0..1b60f35 100644
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -1596,6 +1596,17 @@ XML_ParserReset(XML_Parser parser, const XML_Char *encodingName) {

   if (parser->m_parentParser)
     return XML_FALSE;
+
+  /* Verify that the encoding name can be stored before any parser state
+     is torn down, so that a failed reset leaves the parser unchanged. */
+  if (encodingName != NULL) {
+    XML_Char *const encodingNameCopy = copyString(encodingName, parser);
+    if (encodingNameCopy == NULL) {
+      parser->m_errorCode = XML_ERROR_NO_MEMORY;
+      return XML_FALSE;
+    }
+    FREE(parser, encodingNameCopy);
+  }
   /* move m_tagStack to m_freeTagList */
   tStk = parser->m_tagStack;
   while (tStk) {

